-- evt:treasury_gate
RegisterEvent(38, "Treasury gate", function()
    if not ((IsAtLeast(MapVar(2), 1)) and (IsAtLeast(MapVar(1), 1))) then
        local w = IsAtLeast(MapVar(2), 1)
        local e = IsAtLeast(MapVar(1), 1)
        local s = 'The treasury gate will not move: two iron bars stand before it, each worked by a stone button somewhere in the temple (the clerics keep one in a chapel, one among their books). '
        if w then s = s .. 'The west bar is sunk; ' else s = s .. 'The west bar is up; ' end
        if e then s = s .. 'the east bar is sunk.' else s = s .. 'the east bar is up.' end
        evt.SimpleMessage(s)
        evt.StatusText("The treasury gate is barred.")
        return
    end
    evt.SetDoorState(12, DoorAction.Open)
    evt.StatusText("With both bars sunk, the treasury gate lifts.", 5)
end, "Treasury gate")

