-- evt:yak_pool
RegisterEvent(40, "Yak Pool", function()
    if not (not (IsPlayerBitSet(PlayerBit(10400)))) then
        SetValue(DiseasedGreen, 0)
        evt.StatusText("The pool makes you ill.")
        return
    end
    SetPlayerBit(PlayerBit(10400))
    AddValue(BaseEndurance, 2)
    SetValue(DiseasedGreen, 0)
    evt.StatusText("You drink from the Yak Pool. Strength runs through your limbs (+2 Endurance, permanent), and then the sickness takes you: the pool makes you ill.", 6)
end, "Yak Pool")

